<?php
// Writes src/tests/RatingVectors.kpp: what the PHP version's rating code gives for a grid of inputs
// (calculateNewRating, ranks, showHandicap, getRatingJumpReason, PHP's printing of doubles), for
// src/tests/RatingTests.kpp to check the kpp version against. Usage, in kpp/:
//   php testdata/generate_rating_tests.php
chdir(__DIR__."/../..");
require("src/constants.php");
require("src/rating_helper.php");
$out = "// Generated by testdata/generate_rating_tests.php from PHP ".PHP_VERSION."'s src/rating_helper.php. Do not edit.\n\n";

$out .= "// {rating, opponent, result, game type, extra handicap, extra komi, new rating as %.17g}\nconst double ratingFormulaVectors[][7] = {\n";
$count = 0;
foreach ([-900, 100, 1050.5, 1734.25, 2100, 2650, 2799.9] as $rating)
  foreach ([-500, 1200, 2050, 2700] as $opponent)
    foreach ([0, 0.5, 1] as $result)
      foreach ([1, 3, 5, 7] as $type)
        foreach ([[0, 0], [2, 0], [-3, 0], [0, -6], [1, 6.5]] as [$handicap, $komi])
        {
          $out .= sprintf("  {%.17g, %.17g, %.17g, %d, %.17g, %.17g, %.17g},\n", $rating, $opponent, $result, $type, $handicap, $komi,
                          calculateNewRating($rating, $opponent, $result, $type, $handicap, $komi));
          $count++;
        }
$out .= "};\nconst int ratingFormulaVectorCount = $count;\n\n";

$out .= "// {rating, its rank as readableRank(rankFromRating(rating))}\nconst char* rankVectors[][2] = {\n";
$count = 0;
foreach ([-2000, -950, -850.01, -850, 49.99, 50, 1949.999, 1950, 2049.9, 2050, 2650, 2750, 3000] as $rating)
{
  $out .= sprintf("  {\"%.17g\", \"%s\"},\n", $rating, readableRank(rankFromRating($rating)));
  $count++;
}
$out .= "};\nconst int rankVectorCount = $count;\n\n";

$out .= "// {handicap, komi as the database writes them, showHandicap}\nconst char* handicapVectors[][3] = {\n";
$count = 0;
foreach ([["0", "6.5"], ["0", "7.5"], ["0", "0.5"], ["0", "5"], ["2", "0.5"], ["3", "5.5"], ["9", "0"]] as [$h, $k])
{
  $out .= sprintf("  {\"%s\", \"%s\", \"%s\"},\n", $h, $k, showHandicap($h, $k));
  $count++;
}
$out .= "};\nconst int handicapVectorCount = $count;\n\n";

$out .= "// {reported, first round, last start (or -99999 for none), last end, getRatingJumpReason}\nconst double jumpVectors[][5] = {\n";
$count = 0;
foreach ([[2730, 1, 2600, 2650], [2745, 1, 2600, 2650], [1500, 1, 1290, 1480], [1500, 1, 1390, 1480], [1500, 1, 1340, 1430],
          [1550, 1, 1300, 1480], [1500, 0, 1290, 1480], [1500, 1, null, 1480], [1400, 1, 1100, 1350], [1400, 1, 1150, 1351]] as [$r, $f, $s, $e])
{
  $out .= sprintf("  {%.17g, %d, %.17g, %.17g, %d},\n", $r, $f, $s === null ? -99999 : $s, $e,
                  getRatingJumpReason(0, $r, $f, $s, $e));
  $count++;
}
$out .= "};\nconst int jumpVectorCount = $count;\n\n";

$out .= "// {a double as %.17g, as PHP writes it into SQL (precision 14)}\nconst char* phpNumberVectors[][2] = {\n";
$count = 0;
foreach ([1523.456789012345678, 2/3, 1e20/3, 0.1 + 0.2, -0.0001234567890123456, 100.0, 2273.736 + -3.157, 1e-7, -1e15, 123456789012345.6] as $x)
{
  $out .= sprintf("  {\"%.17g\", \"%s\"},\n", $x, "".$x);
  $count++;
}
$out .= "};\nconst int phpNumberVectorCount = $count;\n";
file_put_contents(__DIR__."/../src/tests/RatingVectors.kpp", $out);
